CREATE TABLE metric_materializations
(
    id                 VARCHAR(50)  NOT NULL,
    name               VARCHAR(200),
    metric_id          VARCHAR(50)  NOT NULL,
    metric_name        VARCHAR(255) NOT NULL,
    metric_label       VARCHAR(255),
    target_topic_id    VARCHAR(50),
    target_topic_name  VARCHAR(200),
    auto_create_topic  TINYINT      NOT NULL,
    time_grain         VARCHAR(10)  NOT NULL,
    group_by           JSON,
    write_mode         VARCHAR(20)  NOT NULL,
    engine             VARCHAR(20)  NOT NULL,
    frequency          VARCHAR(20),
    time               VARCHAR(10),
    date               VARCHAR(20),
    weekday            VARCHAR(10),
    day_of_month       INT,
    schedule_enabled   TINYINT      NOT NULL,
    enabled            TINYINT      NOT NULL,
    factor_mapping     JSON,
    description        VARCHAR(1024),
    tenant_id          VARCHAR(50)  NOT NULL,
    created_at         DATETIME     NOT NULL,
    created_by         VARCHAR(50)  NOT NULL,
    last_modified_at   DATETIME     NOT NULL,
    last_modified_by   VARCHAR(50)  NOT NULL,
    user_id            VARCHAR(50)  NOT NULL,
    PRIMARY KEY (id),
    INDEX (metric_id),
    INDEX (target_topic_id),
    INDEX (tenant_id),
    INDEX (user_id)
);
